H.background();
const rho = 1000;
const v1 = Math.max(0.1, P.v1);
const P1 = P.p1 * 1000;
const ratio = H.clamp(P.ratio, 0.2, 0.95);
const w = H.W, h = H.H;
const cx = w / 2, midY = h * 0.52;
const R1 = 78, R2 = R1 * ratio;
const A1 = R1 * R1, A2 = R2 * R2;
const v2 = v1 * A1 / A2;
const P2 = P1 + 0.5 * rho * (v1 * v1 - v2 * v2);
const xL = 60, xR = w - 60, xa = w * 0.36, xb = w * 0.64;
function radAt(x) {
  if (x <= xa) return R1;
  if (x >= xb) return R1;
  const u = (x - xa) / (xb - xa);
  const s = 0.5 - 0.5 * Math.cos(u * Math.PI);
  return R1 + (R2 - R1) * s;
}
const topPts = [], botPts = [];
for (let x = xL; x <= xR; x += 6) { const r = radAt(x); topPts.push([x, midY - r]); }
for (let x = xR; x >= xL; x -= 6) { const r = radAt(x); botPts.push([x, midY + r]); }
H.path(topPts.concat(botPts), { color: H.colors.axis, width: 2.5, fill: "rgba(124,196,255,0.10)", close: true });
H.path(topPts, { color: H.colors.accent, width: 3 });
const botUp = botPts.slice().reverse();
H.path(botUp, { color: H.colors.accent, width: 3 });
const lanes = 5;
for (let li = 0; li < lanes; li++) {
  const frac = (li + 0.5) / lanes - 0.5;
  const pts = [];
  for (let x = xL; x <= xR; x += 8) {
    const r = radAt(x);
    pts.push([x, midY + frac * 2 * r]);
  }
  H.path(pts, { color: "rgba(103,232,176,0.35)", width: 1.2 });
}
const nDots = 7;
for (let di = 0; di < nDots; di++) {
  const span = xR - xL;
  const phase = (t * v1 * 0.18 + di / nDots) % 1;
  let xpos = xL + phase * span;
  const r = radAt(xpos);
  const frac = ((di % lanes) + 0.5) / lanes - 0.5;
  const ypos = midY + frac * 2 * r * 0.85;
  const localSpeed = v1 * (R1 * R1) / (radAt(xpos) * radAt(xpos));
  const arrowLen = H.clamp(localSpeed * 1.1, 6, 40);
  H.arrow(xpos, ypos, xpos + arrowLen, ypos, { color: H.colors.warn, width: 2, head: 6 });
  H.circle(xpos, ypos, 3, { fill: H.colors.yellow });
}
function pressureH(Pval) { return H.clamp(40 + Pval / 1500, 10, 130); }
const stations = [{ x: xa - 30, r: R1, v: v1, P: P1, lbl: "wide" }, { x: cx, r: R2, v: v2, P: P2, lbl: "throat" }];
stations.forEach(st => {
  const colTop = midY - radAt(st.x) - 6;
  const hh = pressureH(st.P);
  H.line(st.x, colTop, st.x, colTop - 8, { color: H.colors.sub, width: 1.5 });
  H.rect(st.x - 7, colTop - 8 - hh, 14, hh, { fill: H.colors.violet, stroke: H.colors.ink, width: 1 });
  H.text("P=" + (st.P / 1000).toFixed(1) + "kPa", st.x, colTop - 12 - hh, { color: H.colors.violet, size: 11, align: "center" });
  H.text("v=" + st.v.toFixed(1), st.x, midY + radAt(st.x) + 18, { color: H.colors.warn, size: 11, align: "center" });
});
