H.text("Continuity A₁v₁ = A₂v₂ → faster flow in the throat → lower pressure", 24, 52, { color: H.colors.sub, size: 12 });
H.text("ρ = 1000 kg/m³   v₁ = " + v1.toFixed(1) + " m/s   v₂ = " + v2.toFixed(1) + " m/s   ΔP = " + ((P2 - P1) / 1000).toFixed(2) + " kPa", 24, h - 18, { color: H.colors.good, size: 13 });
